// Neon Escape – minimal endless runner
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const resize = () => { canvas.width = innerWidth; canvas.height = innerHeight; };
  resize();
  addEventListener('resize', resize);

  const player = { x: innerWidth / 2, y: innerHeight - 40, radius: 12, speed: 5, boost: false };
  const keys = {};
  onkeydown = e => (keys[e.key] = true);
  onkeyup = e => (keys[e.key] = false);

  // tunnel slices: each slice = { y, left, right }
  const tunnel = [];
  const sliceHeight = 30;
  const baseWidth = innerWidth * 0.6;
  const amplitude = innerWidth * 0.2;
  let offset = 0;

input.oldString:
// draw
ctx.fillStyle = '#000';
ctx.fillRect(0, 0, canvas.width, canvas.height);
// tunnel walls
ctx.strokeStyle = '#0ff';
ctx.lineWidth = 4;
ctx.beginPath();
tunnel.forEach((s, i) => {
  const x = i === 0 ? s.left : tunnel[i - 1].left;
  ctx.moveTo(x, s.y);
  ctx.lineTo(s.left, s.y + sliceHeight);
});
ctx.stroke();
ctx.beginPath();
tunnel.forEach((s, i) => {
  const x = i === 0 ? s.right : tunnel[i - 1].right;
  ctx.moveTo(x, s.y);
  ctx.lineTo(s.right, s.y + sliceHeight);
});
ctx.stroke();
// player
ctx.fillStyle = '#ff0';
ctx.beginPath();
ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
ctx.fill();
// UI
ctx.fillStyle = '#fff';
ctx.font = '16px monospace';
ctx.fillText('Score: ' + Math.floor(score / 100), 10, 30);

input.newString:
// draw enhanced graphics
// background gradient
const bgGrad = ctx.createLinearGradient(0, 0, 0, canvas.height);
bgGrad.addColorStop(0, '#001020');
bgGrad.addColorStop(1, '#000030');
ctx.fillStyle = bgGrad;
ctx.fillRect(0, 0, canvas.width, canvas.height);

// tunnel walls with neon glow
ctx.strokeStyle = 'rgba(0,255,255,0.8)';
ctx.lineWidth = 4;
ctx.shadowColor = '#0ff';
ctx.shadowBlur = 12;
ctx.beginPath();
tunnel.forEach((s, i) => {
  const prev = i === 0 ? s.left : tunnel[i - 1].left;
  ctx.moveTo(prev, s.y);
  ctx.lineTo(s.left, s.y + sliceHeight);
});
ctx.stroke();
ctx.beginPath();
tunnel.forEach((s, i) => {
  const prev = i === 0 ? s.right : tunnel[i - 1].right;
  ctx.moveTo(prev, s.y);
  ctx.lineTo(s.right, s.y + sliceHeight);
});
ctx.stroke();

// optional: glowing particles (simple implementation)
if (!window.__particles) window.__particles = [];
const particles = window.__particles;
// spawn particles near player when boosting
if (player.boost) {
  for (let i = 0; i < 2; i++) {
    particles.push({
      x: player.x + (Math.random() - 0.5) * 20,
      y: player.y + player.radius,
      r: Math.random() * 3 + 2,
      vx: (Math.random() - 0.5) * 0.5,
      vy: Math.random() * 1 + 0.5,
      life: 30
    });
  }
}
// update and draw particles
ctx.globalCompositeOperation = 'lighter';
ctx.fillStyle = 'rgba(0,255,255,0.7)';
for (let i = particles.length - 1; i >= 0; i--) {
  const p = particles[i];
  p.x += p.vx;
  p.y += p.vy;
  p.life--;
  ctx.beginPath();
  ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
  ctx.fill();
  if (p.life <= 0) particles.splice(i, 1);
}
ctx.globalCompositeOperation = 'source-over';
ctx.shadowBlur = 0;

// player with inner glow
ctx.fillStyle = '#ff0';
ctx.beginPath();
ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
ctx.fill();
ctx.strokeStyle = 'rgba(255,255,0,0.6)';
ctx.lineWidth = 2;
ctx.stroke();

// UI
ctx.fillStyle = '#fff';
ctx.font = '16px monospace';
ctx.fillText('Score: ' + Math.floor(score / 100), 10, 30);

